// Chat image store: images attached to chat messages (pasted, dropped, picked, or generated by the
// art tools) live as files under userData/chat-images/<id>.<ext>. Chat history keeps only
// ChatImage references, so saved chats stay small; bytes are read back when a request is built
// or the renderer asks for a thumbnail.
//
// Tools that produce an image put imageMarker(ref) in their text result; ChatManager turns
// markers into message images (extractImageMarkers), on every provider path.

import { randomUUID } from 'node:crypto'
import { mkdir, readFile, stat, writeFile } from 'node:fs/promises'
import { basename, extname, join } from 'node:path'
import type { ChatImage, ChatImageInput } from '@shared/types'
import { IMAGE_MIMES, type ImageMime } from '../../shared/modelCaps.ts'

// Larger inputs are refused (the renderer downscales before adding; generated art is far smaller).
export const MAX_IMAGE_BYTES = 20 * 1024 * 1024

const EXT: Record<ImageMime, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }
const ID = /^[a-f0-9-]{36}$/

export function isImageMime(v: string): v is ImageMime {
  return (IMAGE_MIMES as readonly string[]).includes(v)
}

// Image type from the file's magic bytes (the extension or a data: URL header can lie).
export function sniffMime(b: Uint8Array): ImageMime | null {
  if (b.length >= 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return 'image/png'
  if (b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg'
  if (b.length >= 6 && b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) return 'image/gif'
  if (b.length >= 12 && String.fromCharCode(...b.subarray(0, 4)) === 'RIFF' && String.fromCharCode(...b.subarray(8, 12)) === 'WEBP') return 'image/webp'
  return null
}

// Pixel size from the header (PNG IHDR, GIF screen descriptor, JPEG SOFn, WebP VP8/VP8L/VP8X).
export function imageSize(b: Uint8Array): { width: number; height: number } | null {
  const mime = sniffMime(b)
  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength)
  try {
    if (mime === 'image/png') return { width: dv.getUint32(16), height: dv.getUint32(20) }
    if (mime === 'image/gif') return { width: dv.getUint16(6, true), height: dv.getUint16(8, true) }
    if (mime === 'image/jpeg') {
      let i = 2
      while (i + 9 < b.length) {
        if (b[i] !== 0xff) return null
        const marker = b[i + 1]
        const len = dv.getUint16(i + 2)
        if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) return { width: dv.getUint16(i + 7), height: dv.getUint16(i + 5) }
        i += 2 + len
      }
      return null
    }
    if (mime === 'image/webp') {
      const chunk = String.fromCharCode(...b.subarray(12, 16))
      if (chunk === 'VP8 ') return { width: dv.getUint16(26, true) & 0x3fff, height: dv.getUint16(28, true) & 0x3fff }
      if (chunk === 'VP8L') {
        const bits = dv.getUint32(21, true)
        return { width: (bits & 0x3fff) + 1, height: ((bits >> 14) & 0x3fff) + 1 }
      }
      if (chunk === 'VP8X') return { width: 1 + (b[24] | (b[25] << 8) | (b[26] << 16)), height: 1 + (b[27] | (b[28] << 8) | (b[29] << 16)) }
    }
  } catch {
    return null
  }
  return null
}

export function parseDataUrl(url: string): { mime: string; data: Buffer } | null {
  const m = /^data:([\w/+.-]+);base64,([A-Za-z0-9+/=\s]+)$/.exec(url.trim())
  if (!m) return null
  return { mime: m[1].toLowerCase(), data: Buffer.from(m[2], 'base64') }
}

// ---------------------------------------------------------------- markers

export const MARKER_SCHEME = 'forge-image://'

// Markdown image line a tool result can carry: ![name](forge-image://<id>)
export function imageMarker(ref: Pick<ChatImage, 'id' | 'name'>): string {
  const alt = (ref.name ?? 'image').replace(/[[\]\n]/g, ' ')
  return `![${alt}](${MARKER_SCHEME}${ref.id})`
}

// Splits markers out of text: the ids in order, and the text without the marker lines.
export function extractImageMarkers(text: string): { text: string; ids: { id: string; name?: string }[] } {
  const ids: { id: string; name?: string }[] = []
  if (!text.includes(MARKER_SCHEME)) return { text, ids }
  const out = text.replace(/!\[([^\]\n]*)\]\(forge-image:\/\/([a-f0-9-]{36})\)/g, (_, name: string, id: string) => {
    if (!ids.some((x) => x.id === id)) ids.push({ id, ...(name ? { name } : {}) })
    return ''
  })
  return { text: out.replace(/\n{3,}/g, '\n\n').trim(), ids }
}

// ---------------------------------------------------------------- store

export class ChatImageStore {
  readonly dir: string
  private meta = new Map<string, ChatImage>()

  constructor(dir: string) {
    this.dir = dir
  }

  private file(id: string, mime: ImageMime): string {
    return join(this.dir, `${id}.${EXT[mime]}`)
  }

  async add(input: ChatImageInput): Promise<ChatImage> {
    let data: Buffer
    let name = input.name?.trim() || undefined
    if (input.dataUrl) {
      const parsed = parseDataUrl(input.dataUrl)
      if (!parsed) throw new Error('not a base64 data URL')
      data = parsed.data
    } else if (input.path) {
      const s = await stat(input.path)
      if (!s.isFile()) throw new Error('not a file')
      if (s.size > MAX_IMAGE_BYTES) throw new Error('image is larger than 20 MB')
      data = await readFile(input.path)
      name ??= basename(input.path, extname(input.path))
    } else throw new Error('an image needs a dataUrl or a path')
    if (data.length > MAX_IMAGE_BYTES) throw new Error('image is larger than 20 MB')
    const mime = sniffMime(data)
    if (!mime) throw new Error('only PNG, JPEG, WebP and GIF images are supported')
    const size = imageSize(data)
    const ref: ChatImage = { id: randomUUID(), mime, bytes: data.length, ...(name ? { name: name.slice(0, 80) } : {}), ...(size ? size : {}) }
    await mkdir(this.dir, { recursive: true })
    await writeFile(this.file(ref.id, mime), data)
    this.meta.set(ref.id, ref)
    return ref
  }

  // Copies an image file into the store (generated art, "Send to chat").
  importFile(path: string, name?: string): Promise<ChatImage> {
    return this.add({ path, name })
  }

  // Bytes and type of a stored image, or null when it is gone.
  async read(id: string): Promise<{ mime: ImageMime; data: Buffer } | null> {
    if (!ID.test(id)) return null
    for (const mime of IMAGE_MIMES) {
      try {
        return { mime, data: await readFile(this.file(id, mime)) }
      } catch {
        // try the next extension
      }
    }
    return null
  }

  // File of a stored image (Codex takes images as paths), or null when it is gone.
  async pathOf(id: string): Promise<string | null> {
    if (!ID.test(id)) return null
    for (const mime of IMAGE_MIMES) {
      const file = this.file(id, mime)
      if (await stat(file).then((s) => s.isFile()).catch(() => false)) return file
    }
    return null
  }

  async base64(id: string): Promise<{ mime: ImageMime; base64: string } | null> {
    const r = await this.read(id)
    return r ? { mime: r.mime, base64: r.data.toString('base64') } : null
  }

  async dataUrl(id: string): Promise<string> {
    const r = await this.base64(id)
    if (!r) throw new Error('image not found')
    return `data:${r.mime};base64,${r.base64}`
  }

  // Known reference without touching the disk (images added in this process).
  peek(id: string): ChatImage | undefined {
    return this.meta.get(id)
  }

  // Reference for an id (size from the header), for markers produced by tools.
  async ref(id: string, name?: string): Promise<ChatImage | null> {
    const known = this.meta.get(id)
    if (known) return name && !known.name ? { ...known, name } : known
    const r = await this.read(id)
    if (!r) return null
    const size = imageSize(r.data)
    const ref: ChatImage = { id, mime: r.mime, bytes: r.data.length, ...(name ? { name } : {}), ...(size ? size : {}) }
    this.meta.set(id, ref)
    return ref
  }
}

// Process-wide store, set once by registerAgentIpc (tools in other modules import it).
let current: ChatImageStore | null = null

export function setChatImageStore(store: ChatImageStore): void {
  current = store
}

export function chatImageStore(): ChatImageStore {
  if (!current) throw new Error('chat image store is not ready')
  return current
}

export function hasChatImageStore(): boolean {
  return !!current
}
